import unittest
from candidate import prime_fib

class TestPrimeFib(unittest.TestCase):
    def test_prime_fib_first_number(self):
        self.assertEqual(prime_fib(1), 2)

    def test_prime_fib_second_number(self):
        self.assertEqual(prime_fib(2), 3)

    def test_prime_fib_third_number(self):
        self.assertEqual(prime_fib(3), 5)

    def test_prime_fib_fourth_number(self):
        self.assertEqual(prime_fib(4), 13)

    def test_prime_fib_fifth_number(self):
        self.assertEqual(prime_fib(5), 89)

    def test_prime_fib_input_zero(self):
        with self.assertRaises(ValueError):
            prime_fib(0)

    def test_prime_fib_input_negative(self):
        with self.assertRaises(ValueError):
            prime_fib(-1)

    def test_prime_fib_input_non_integer(self):
        with self.assertRaises(TypeError):
            prime_fib(1.5)

    def test_prime_fib_input_none(self):
        with self.assertRaises(TypeError):
            prime_fib(None)

if __name__ == '__main__':
    unittest.main()
